use clap::{Arg, Command};
use std::time::Instant;

#[path = "benchmark_convergence/benchmark_comparison.rs"]
mod benchmark_comparison;
#[path = "benchmark_convergence/benchmark_config.rs"]
mod benchmark_config;
#[path = "benchmark_convergence/benchmark_result.rs"]
mod benchmark_result;
#[path = "benchmark_convergence/cmaes.rs"]
mod cmaes;
#[path = "benchmark_convergence/function_registry.rs"]
mod function_registry;
