mod types;

use benchmark_comparison::BenchmarkComparison;
use benchmark_comparison::generate_all_benchmarks;
use misc::mean_std;
use print::print_compact_comparison;
use print::print_verbose_comparison;

fn main() {
    let matches = Command::new("benchmark_convergence")
        .version("0.1.0")
        .about("Runs optimization convergence benchmarks and reports success/failure")
        .arg(
            Arg::new("filter")
                .short('f')
                .long("filter")
                .value_name("PATTERN")
                .help("Only run benchmarks matching this pattern")
                .num_args(1),
        )
        .arg(
            Arg::new("list")
                .short('l')
                .long("list")
                .help("List available benchmarks")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .help("Show detailed results for each benchmark")
                .action(clap::ArgAction::SetTrue),
        )
        .get_matches();

    // Generate benchmarks dynamically from function metadata
    let benchmarks = generate_all_benchmarks();

    if matches.get_flag("list") {
        println!("Available benchmarks:");
        let mut names: Vec<_> = benchmarks.keys().collect();
        names.sort();
        for name in names {
            println!("  {}", name);
        }
        return;
    }

    let filter = matches.get_one::<String>("filter");
    let verbose = matches.get_flag("verbose");

    // Filter benchmarks if a pattern is provided
    let mut selected_benchmarks: Vec<_> = benchmarks
        .keys()
        .filter(|name| {
            if let Some(pattern) = filter {
                name.contains(pattern)
            } else {
                true
            }
        })
        .collect();
    selected_benchmarks.sort();

    if selected_benchmarks.is_empty() {
        eprintln!("No benchmarks match the filter criteria");
        std::process::exit(1);
    }

    println!("Running {} benchmark(s)...", selected_benchmarks.len());

    let mut results = Vec::new();
    let total_start = Instant::now();

    for &name in &selected_benchmarks {
        println!("Running {}...", name);
        let benchmark_fn = &benchmarks[name];
        let comparison = benchmark_fn();

        if verbose {
            print_verbose_comparison(&comparison);
        } else {
            print_compact_comparison(&comparison);
        }

        results.push(comparison);
    }

    let total_duration = total_start.elapsed();

    // Summary
    println!("\n=== BENCHMARK SUMMARY ===");
    let total = results.len();
    let de_passed = results.iter().filter(|r| r.de.success).count();
    let cmaes_passed = results.iter().filter(|r| r.cmaes.success).count();
    let both_passed = results
        .iter()
        .filter(|r| r.de.success && r.cmaes.success)
        .count();
    let failed = results.iter().filter(|r| r.has_failure()).count();
    let failed_optimizer_runs = (total - de_passed) + (total - cmaes_passed);

    println!("L-SHADE passed: {} / {}", de_passed, total);
    println!("CMA-ES passed: {} / {}", cmaes_passed, total);
    println!("Both passed: {} / {}", both_passed, total);
    println!("Comparison failures: {}", failed);
    println!("Failed optimizer runs: {}", failed_optimizer_runs);

    let deltas: Vec<f64> = results
        .iter()
        .filter_map(BenchmarkComparison::cmaes_minus_de)
        .collect();
    let cmaes_lower = deltas.iter().filter(|&&d| d < -1e-12).count();
    let tied = deltas.iter().filter(|&&d| d.abs() <= 1e-12).count();
    let de_lower = deltas.len() - cmaes_lower - tied;
    println!(
        "Final objective, lower is better: CMA-ES lower / tied / L-SHADE lower = {} / {} / {}",
        cmaes_lower, tied, de_lower
    );
    if let Some((mean, std)) = mean_std(&deltas) {
        println!("cmaes_minus_lshade: mean={:+.6e}, std={:.6e}", mean, std);
    }
    println!("Total time: {:.2}s", total_duration.as_secs_f64());

    if !verbose && failed > 0 {
        println!("\nDetailed results:");
        for comparison in &results {
            println!("  {}", comparison.name);
            print_verbose_comparison(comparison);
        }
    }

    if failed == 0 {
        println!("\n🎉 All benchmarks passed!");
        std::process::exit(0);
    } else {
        println!("\n💥 {} benchmark(s) failed", failed);
        std::process::exit(1);
    }
}
